mapper.select:
SELECT bo.id, bo.order_no, rt.type_name as roomTypeName, bo.room_price as roomPrice, bo.check_in_date , bo.check_out_date , bo.days, bo.total_amount, bo.status, bo.create_time FROM booking_order bo LEFT JOIN room_type rt ON bo.room_type_id = rt.id WHERE bo.user_id = #{userId}
AND bo.status = #{status}
ORDER BY bo.create_time DESC

mapper.update:
UPDATE booking_order
room_type_id = #{roomTypeId}, room_price = #{roomPrice}, check_in_date = #{checkInDate}, check_out_date = #{checkOutDate}, days = #{days}, guest_name = #{guestName}, guest_phone = #{guestPhone}, guest_id_card = #{guestIdCard}, total_amount = #{totalAmount}, status = #{status}, update_time = SYSDATE
WHERE id = #{id}
